L000602	\section{End Matter}
L000603	\textit{Models for polarization buildup} ---
L000604	Two models have been developed for the single-bunch and pilot-bunch methods to describe the polarization buildup and to extract the resonance strength $\epsilon$. Deviations from the ideal behavior described by Eq.~(\ref{eq:oscwf}) arise from decoherence and from deviations from the resonance frequency.
L000605	Spin decoherence leads to a decay of the in-plane polarization, thereby reducing the effective contribution of spin rotation from horizontal to vertical polarization over time~\cite{Hempelmann:718035,PhysRevAccelBeams.27.111002}. This effect must be taken into account, in particular for finite spin-coherence times, to reliably determine the resonance strength from the initial slope or the oscillation frequency. Deviations from exact resonance account for the finite precision of the phase-lock feedback~\cite{PhysRevAccelBeams.28.062801}.
L000606	
L000607	\textit{Polarization buildup using a single bunch} ---
L000608	Decoherence is taken into account by fitting the out-of-plane angle $\alpha(t)$ of the polarization vector and the total polarization $p_\mathrm{tot}(t)$ simultaneously, where
L000609	\begin{eqnarray}
L000610	    \alpha(t) &=& \arctan(p_v(t)/p_h(t)), \\
L000611	    p_\mathrm{tot}(t) &=& \sqrt{p_v(t)^2 + p_h(t)^2},
L000612	\end{eqnarray}
L000613	where $p_h(t)$ and $p_v(t)$ denote the in-plane and the vertical polarization, respectively.
L000614	Note that the vertical polarization $p_v$ corresponds to the spin component $S_y$ in Eq.~\ref{eq:oscwf}.
L000615	Assuming an exponential decay of the in-plane polarization, characterized by
L000616	\begin{equation}
L000617	-\frac{1}{p_h(t)}\cdot\frac{\mathrm{d}p_h(t)}{\mathrm{d}t} = \mathrm{const}. = B,
L000618	\end{equation}
L000619	this results in a non-linear term for $\alpha(t)$, which includes the constant spin kick per turn $A = 2\pi\epsilon\fc \sin\phirel$ as one of its parameters (cf. Eq. (5.13) and (5.14) in \cite{Hempelmann:718035})
L000620	\begin{equation}
L000621	\begin{aligned}
L000622	\tan&(\alpha(t)) = \\[-1mm]
L000623	&\begin{cases}
L000624	\tan(\alpha_0) e^{B t}, & A = 0, \\[2mm]
L000625	\frac{1}{2A} \left( \sqrt{E} \frac{D + \tan\left(\frac{t}{2}\sqrt{E}\right)}{1 - D \tan\left(\frac{t}{2}\sqrt{E}\right)} - B \right), & E > 0, \\[1mm]
L000626	\frac{1}{2A} \left( \sqrt{-E} \frac{D - \tanh\left(\frac{t}{2}\sqrt{-E}\right)}{1 - D \tanh\left(\frac{t}{2}\sqrt{-E}\right)} - B \right), & E < 0,
L000627	\end{cases} \\[1mm]
L000628	&\text{with } D = \frac{2A \tan(\alpha_0) + B}{\sqrt{|E|}}, \quad E = 4A^2 - B^2
L000629	\end{aligned}
L000630	\end{equation}
L000631	and
L000632	\begin{equation}
L000633	  \begin{aligned}
L000634	    &\log \left(\frac{p_{\text{tot}}(t)}{p_{\text{tot},0}}\right)= \frac{1}{2} \log \left(\frac{2 A+B \sin \left(2\alpha_{0}\right)}{2 A+B \sin(2 \alpha(t))}\right)+ \\ &\begin{cases}
L000635	    \frac{B}{\sqrt{E}} \arctan \left(\frac{\sin\left(\alpha_{0}-\alpha(t)\right) \sqrt{E}}{2 A \cos\left(\alpha_{0}-\alpha(t)\right)+B \sin\left(\alpha_{0}+\alpha(t)\right)}\right), & E>0, \\
L000636	    \frac{B}{\sqrt{-E}} \operatorname{artanh}\left(\frac{\sin \left(\alpha_{0}-\alpha(t)\right) \sqrt{-E}}{2 A \cos \left(\alpha_{0}-\alpha(t)\right)+B \sin \left(\alpha_{0}+\alpha(t)\right)}\right), & E<0.
L000637	  \end{cases}
L000638	  \end{aligned}
L000639	\end{equation}
L000640	where $\alpha_0$ and $p_{\text{tot},0}$ denote the initial out-of-plane angle and initial total polarization.
L000641	
L000642	\textit{Polarization buildup using a pilot bunch} ---
L000643	This case including decoherence and off-resonance behavior is discussed in \cite{PhysRevAccelBeams.27.111002}.
L000644	The underlying formalism describes the time evolution of the polarization vector~$\vec{p}$ after a time interval $x$, described in terms of a dimensionless variable,
L000645	\begin{equation}
L000646	x = 2\pi \epsilon_{\text{m}} (n - n_{\text{WF}}^{\text{on}})
L000647	\; \text{or} \;
L000648	x = 2\pi \epsilon_{\text{m}} \fc (t - t_{\text{WF}}^{\text{on}}),
L000649	\end{equation}
L000650	where $n$ denotes the turn number and $\epsilon_{\text{m}}$ the measured resonance strength. Here, $x_{\text{WF}}^{\text{on}} = 2\pi \epsilon_{\text{m}} n_{\text{WF}}^{\text{on}}$ corresponds to the time when the rf Wien filter is switched on.
L000651	The polarization vector is expressed as
L000652	\begin{equation}
L000653	  \vec{p}(x) = \mathbf{E}(x) \cdot \vec{p}(x = x_{\text{WF}}^{\text{on}}),
L000654	\end{equation}
L000655	with $\vec{p} = (p_{\text{r}}, p_{\text{v}}, p_{\text{t}})^{\text{T}}$.
L000656	The vertical component $p_{\text{v}}$ is oriented along the invariant spin axis~$\vec{n}$, the tangential component $p_{\text{t}}$ is defined along the beam direction, and the radial component $p_{\text{r}}$ lies perpendicular to both $\vec{n}$ and $p_{\text{t}}$.
L000657	The polarization transfer matrix $\mathbf{E}(x)$ is given by Eq.~(91) in \cite{PhysRevAccelBeams.27.111002}.
L000658	The initial polarization condition for the experiment is defined by
L000659	\begin{equation}
L000660	  \vec{p}(x = x_{\text{WF}}^\text{on}) =
L000661	  \left(\begin{array}{c}
L000662	    p_{\text{h},0}\sin(\phirelzero)\\
L000663	    p_{\text{v},0}\\
L000664	    p_{\text{h},0}\cos(\phirelzero)
L000665	  \end{array}\right),
L000666	\end{equation}
L000667	where $\phirelzero$ denotes the relative phase at the time the rf Wien filter is switched on. The initial in-plane polarization is given by $p_{\text{h},0}^2=p_{\text{r},0}^2+p_{\text{t},0}^2$, and $p_{\text{v},0}$ denotes the initial vertical polarization, which can be non-zero if the rotation of the vertical polarization into the horizontal plane by the rf solenoid is incomplete.
L000668	While the vertical polarization remains preserved over time, an exponential decay of the in-plane polarization is assumed. The decoherence parameter $Q$, related to the Spin Coherence Time $\tau_{\text{SCT}}$, is defined as
L000669	\begin{equation}
L000670	Q=\frac{1}{2\pi\epsilon_{\text{m}}\fc \tau_{\text{SCT}}}.
L000671	\end{equation}
L000672	
L000673	The parameter $\delta$ characterizes the off-resonance behavior and is defined as
L000674	\begin{equation}
L000675	\delta = \frac{2\pi(f_s - f_{\text{WF}})}{\fc}.  \label{eq:off_resonance_delta}
L000676	\end{equation}
L000677	In contrast to these corrections for the Spin Coherence Time, a detuned rf-Wien-filter frequency leads to a systematic shift of the measured resonance strength.
L000678	The measured and the detuned resonance strength are connected via the dimensionless parameter $\rho$
L000679	\begin{equation}
L000680	\sin(\rho) = \frac{\epsilon}{\epsilon_{\text{m}}} \text{ and } \cos(\rho) = \frac{2\delta}{4\pi\epsilon_{\text{m}}}, \label{eq:off_resonance_behaviour}
L000681	\end{equation}
L000682	which allows for the determination of the unbiased resonance strength.
L000683	The tangential, radial and vertical components of the polarization are given by
L000684	\begin{equation}
L000685	  \begin{aligned}
L000686	    p_\text{t} = &-e^{-Qx}\cos(\rho)\sin(x)\cos(\phirelzero)p_{\text{h},0}\\
L000687	          &+e^{-Qx}\sin(\rho)\sin(x)p_{\text{v},0}\\
L000688	          &+e^{-Qx}\cos(x)\sin(\phirelzero)p_{\text{h},0},
L000689	  \end{aligned}
L000690	\end{equation}
L000691	\begin{equation}
L000692	  \begin{aligned}
L000693	    p_\text{r} = & \left[e^{-2Qx}\sin(\rho)^2+e^{-Qx}\cos(\rho)^2\cos(x)\right]\cos(\phirelzero)p_{\text{h},0}\\
L000694	          &+ \left(e^{-2Qx}-e^{-Qx}\cos(x)\right)\cos(\rho)\sin(\rho)p_{\text{v},0} \\
L000695	          & + e^{-Qx}\cos(\rho)\sin(x)\sin(\phirelzero)p_{\text{h},0},
L000696	  \end{aligned}
L000697	\end{equation}
L000698	and
L000699	\begin{equation}
L000700	  \begin{aligned}
L000701	    \pv = & -e^{-2Qx}\cos(\rho)\sin(\rho)\sin(\phirelzero)p_{\text{h},0}\\
L000702	            & +e^{-Qx}\cos(\rho)\sin(\rho)\cos(x)\sin(\phirelzero)p_{\text{h},0}\\
L000703	            & + \left[e^{-2Qx}\cos(\rho)^2+e^{-Qx}\sin(\rho)^2\cos(x)\right]p_{\text{v},0} \\
L000704	            & - e^{-Qx}\sin(\rho)\sin(x)\sin(\phirelzero)p_{\text{h},0}.
L000705	  \end{aligned}
L000706	  \label{eq:pilot_bunch_vertical_component}
L000707	\end{equation}
